-- Curated Keep TX Red article for 2026-08-07.
WITH seed AS (
  SELECT
    '2026-08-07-whataburger-76th-birthday-texas-deals'::text AS slug,
    'Non-Political'::text AS category,
    'Whataburger Turns 76 With Texas Birthday Deals — Here’s What Customers Can Get'::text AS title,
    'The Corpus Christi-born chain is marking its 76th birthday with app-based offers, including a buy-one-get-one Whataburger deal on August 8.'::text AS dek,
    'Houston Chronicle'::text AS source_name,
    'https://www.houstonchronicle.com/news/houston-texas/trending/article/whataburger-birthday-week-22373336.php'::text AS source_url,
    '2026-08-07T12:16:00Z'::timestamptz AS published_at,
    23::int AS score,
    FALSE::boolean AS is_breaking,
    '{"updated":"2026-08-07","intro":["Few fast-food brands are as closely tied to Texas identity as Whataburger, and the Corpus Christi-born chain is leaning into that connection for its 76th birthday. Founded on August 8, 1950, Whataburger is celebrating with digital offers that give customers another reason to open the company’s app. The centerpiece is a buy-one-get-one Whataburger offer on August 8 from 11 a.m. to 8 p.m., accompanied by additional 76-cent promotions on selected Wednesdays. For Texans, the campaign is part discount, part nostalgia and part reminder of how deeply the orange-and-white brand has embedded itself in the state."],"sections":[{"heading":"The August 8 birthday offer","paragraphs":["The headline promotion is scheduled for Whataburger’s actual anniversary, August 8. Customers using the chain’s digital channels can access a buy-one-get-one Whataburger offer during the announced 11 a.m. to 8 p.m. window. The promotion is designed around the company’s original signature burger, making the anniversary less about introducing a new menu item and more about returning attention to the product that built the brand.","Digital-only promotions have become a standard tool for restaurant chains because they combine a discount with customer-account activity. A birthday deal can drive traffic while also encouraging occasional customers to download an app, sign in or use online ordering. For diners, that means the practical detail matters: someone who simply walks into a restaurant without using the eligible digital offer may not receive the same promotion."]},{"heading":"Why 76 matters this year","paragraphs":["Whataburger opened its first location in Corpus Christi in 1950, giving the company a Texas origin story that remains central to its public image even as its footprint has expanded. The 76th anniversary is not a conventional milestone like a 75th or 100th birthday, but the company has turned the number itself into the theme of its offers. That makes the campaign easy to remember and gives the chain room to extend the celebration beyond a single day.","Other scheduled promotions reportedly feature 76-cent pricing on selected items on Wednesdays. That approach stretches the birthday into a broader customer-engagement campaign rather than concentrating all demand into one meal period. It also gives fans multiple opportunities to participate, which helps explain why the offers are being widely shared in Texas food groups and local-news feeds."]},{"heading":"A brand Texans treat differently","paragraphs":["Whataburger’s popularity in Texas is not simply a function of restaurant count. For generations of customers, it has been tied to road trips, late-night meals, high-school routines, football weekends and hometown traditions. The company’s distinctive A-frame restaurants and orange branding became visual shorthand for a certain kind of Texas roadside stop. That emotional connection makes even a routine promotion more culturally resonant than a similar discount from a national chain with no state-specific history.","That identity has survived changes in ownership and expansion beyond Texas, though those developments have periodically sparked debate among longtime fans. The birthday campaign benefits from the older story: whatever Texans think about menu changes or new markets, the chain can still point back to Corpus Christi in 1950. An anniversary promotion turns that history into a reason to visit now."]},{"heading":"What customers should check before ordering","paragraphs":["The most important details are timing and redemption method. The buy-one-get-one offer is tied to August 8 and the stated daytime/evening window, while the broader birthday promotions have their own dates and terms. Because the deals are digital, customers should check the Whataburger app or official online ordering channel before arriving rather than assume every item or order method qualifies.","Promotional supplies and restaurant participation can also vary under the terms of restaurant offers, so the official offer displayed in a customer’s account is the best source for the final conditions. That matters on a high-interest promotion because popular locations can become busy quickly. Planning the order through the app can reduce confusion and make it clear which discount is actually being applied."]},{"heading":"Why the deal is spreading online","paragraphs":["Food promotions spread particularly well on social media because they combine immediate utility with a recognizable brand. A user does not have to agree with a political argument or follow a complicated news event to share a free-burger opportunity with family or coworkers. In Texas, the Whataburger name adds another layer of familiarity, giving local pages a reason to treat the promotion as community news rather than just advertising.","The limited-time nature of the birthday offer also creates urgency. August 8 arrives once, and the buy-one-get-one window lasts only part of the day. That is exactly the kind of simple deadline that moves through group chats and local Facebook pages quickly. A person who sees the story Friday morning can make a concrete plan for the weekend, which increases the likelihood that the post is forwarded rather than merely read."]},{"heading":"What the anniversary says about Texas food culture","paragraphs":["Whataburger’s 76 years illustrate how a regional restaurant can become part of a state’s cultural vocabulary. Texas has plenty of homegrown chains, but only a few become symbols that residents use to compare hometowns, remember road trips or explain the state to newcomers. The anniversary is therefore more than a corporate birthday for many longtime customers; it is a marker of shared experience.","That helps explain why Texans can debate Whataburger intensely and still turn out for a birthday deal. Familiarity breeds opinions as well as loyalty. This weekend’s promotion gives both groups—die-hard fans and occasional critics—a low-cost reason to revisit the original burger and decide for themselves how the 76-year-old Texas institution is holding up."]},{"heading":"Source attribution","paragraphs":["This article is an independent Keep TX Red rewrite based on reporting from Houston Chronicle. The original report is linked below for verification."]}],"faq":[],"sources":[{"label":"Houston Chronicle — original report","url":"https://www.houstonchronicle.com/news/houston-texas/trending/article/whataburger-birthday-week-22373336.php"}],"keyTakeaways":["The Corpus Christi-born chain is marking its 76th birthday with app-based offers, including a buy-one-get-one Whataburger deal on August 8."]}'::jsonb AS body_json
), prepared AS (
  SELECT seed.*,
    (SELECT string_agg(value, ' ') FROM jsonb_array_elements_text(
      jsonb_path_query_array(seed.body_json, '$.intro[*]') ||
      jsonb_path_query_array(seed.body_json, '$.sections[*].paragraphs[*]')
    )) AS body_text
  FROM seed
)
INSERT INTO public.daily_articles
  (slug, internal_url, is_ingested, category, title, dek, source_name, source_url,
   published_at, score, is_breaking, kind, body, body_json)
