       published_at, score, is_breaking, 'news', body_text, body_json
FROM prepared
ON CONFLICT (slug) DO UPDATE SET
  internal_url=EXCLUDED.internal_url, is_ingested=EXCLUDED.is_ingested,
  category=EXCLUDED.category, title=EXCLUDED.title, dek=EXCLUDED.dek,
  source_name=EXCLUDED.source_name, source_url=EXCLUDED.source_url,
  published_at=EXCLUDED.published_at, score=EXCLUDED.score,
  is_breaking=EXCLUDED.is_breaking, kind=EXCLUDED.kind,
  body=EXCLUDED.body, body_json=EXCLUDED.body_json;
